const baseObligations=obligations.map(o=>({...o}));
let currentUser=null;
const userKey=(suffix,user=currentUser)=>`impueston_${user?.id}_${suffix}`;
const safe=v=>String(v??'').replaceAll('&','&amp;').replaceAll('<','&lt;').replaceAll('>','&gt;').replaceAll('"','&quot;');
const bytesToHex=bytes=>[...bytes].map(b=>b.toString(16).padStart(2,'0')).join('');
async function passwordHash(password,salt){const material=await crypto.subtle.importKey('raw',new TextEncoder().encode(password),'PBKDF2',false,['deriveBits']);const bits=await crypto.subtle.deriveBits({name:'PBKDF2',salt:new TextEncoder().encode(salt),iterations:120000,hash:'SHA-256'},material,256);return bytesToHex(new Uint8Array(bits))}
function accounts(){return JSON.parse(localStorage.getItem('impueston_accounts_v1')||'[]')}
function saveAccounts(value){localStorage.setItem('impueston_accounts_v1',JSON.stringify(value))}
function persistUserData(){if(!currentUser)return;localStorage.setItem(userKey('records'),JSON.stringify(appState.records));localStorage.setItem(userKey('documents'),JSON.stringify(appState.documents));localStorage.setItem(userKey('settings'),JSON.stringify(appState.settings));localStorage.setItem(userKey('obligations'),JSON.stringify(obligations))}
function loadUserData(user){currentUser=user;appState.records=JSON.parse(localStorage.getItem(userKey('records'))||'[]');appState.documents=JSON.parse(localStorage.getItem(userKey('documents'))||'[]');appState.settings=JSON.parse(localStorage.getItem(userKey('settings'))||'null')||{time:'09:00',reminders:['7','3','1','0'],alerts:true};const saved=JSON.parse(localStorage.getItem(userKey('obligations'))||'[]');obligations.splice(0,obligations.length,...saved.map(o=>({...o,active:o.active!==false})));obligations.sort((a,b)=>a.name.localeCompare(b.name,'es',{sensitivity:'base'}));persistUserData()}
function authScreen(mode='login',message=''){const hasAccounts=accounts().length>0;if(!hasAccounts)mode='register';document.querySelector('#app').innerHTML=`<main class="auth-shell"><section class="auth-brand"><div class="brandmark">✓</div><span>IMPUES<span>TON</span></span><h1>Tu agenda impositiva,<br>simple y personal.</h1><p>Organizá impuestos, servicios, comprobantes y vencimientos desde cualquier pantalla.</p><div class="auth-features"><span>✓ Agenda personalizada</span><span>✓ Datos separados por usuario</span><span>✓ Contraseña protegida</span></div></section><section class="auth-card"><span class="modal-kicker">${mode==='register'?'CREAR CUENTA':'BIENVENIDO'}</span><h2>${mode==='register'?'Empezá a organizarte':'Ingresá a ImpuestON'}</h2><p>${mode==='register'?'Creá tu perfil personal en este dispositivo.':'Accedé a tu agenda y tus documentos.'}</p>${message?`<div class="auth-message">${safe(message)}</div>`:''}<form id="authForm"><label>${mode==='register'?'Tu nombre':'Usuario'}<input name="name" autocomplete="username" required placeholder="${mode==='register'?'Ej. Fernando':'Tu usuario'}"></label>${mode==='register'?'<label>Usuario<input name="username" autocomplete="username" minlength="3" required placeholder="Elegí un usuario"></label>':''}<label>Contraseña<input name="password" type="password" autocomplete="${mode==='register'?'new-password':'current-password'}" minlength="6" required placeholder="Mínimo 6 caracteres"></label><button class="primary full" type="submit">${mode==='register'?'Crear mi cuenta':'Ingresar'}</button></form>${hasAccounts?`<button class="auth-switch" id="switchAuth">${mode==='register'?'Ya tengo una cuenta':'Crear otra cuenta'}</button>`:''}<small>Las cuentas y los datos se guardan localmente en este dispositivo.</small></section></main>`;document.querySelector('#switchAuth')?.addEventListener('click',()=>authScreen(mode==='login'?'register':'login'));document.querySelector('#authForm').onsubmit=e=>submitAuth(e,mode)}
async function submitAuth(event,mode){event.preventDefault();const data=Object.fromEntries(new FormData(event.currentTarget));const username=(data.username||data.name).trim().toLowerCase();const list=accounts();if(mode==='register'){if(list.some(u=>u.username===username)){authScreen('register','Ese usuario ya existe.');return}const salt=crypto.randomUUID();const user={id:crypto.randomUUID(),name:data.name.trim(),username,salt,passwordHash:await passwordHash(data.password,salt),created:new Date().toISOString()};saveAccounts([...list,user]);sessionStorage.setItem('impueston_session',user.id);loadUserData(user,list.length===0);render();return}const user=list.find(u=>u.username===username);if(!user||await passwordHash(data.password,user.salt)!==user.passwordHash){authScreen('login','Usuario o contraseña incorrectos.');return}sessionStorage.setItem('impueston_session',user.id);loadUserData(user);render()}
function logout(){persistUserData();sessionStorage.removeItem('impueston_session');currentUser=null;authScreen('login')}
function enhancedNav(){const initials=(currentUser?.name||'U').split(/\s+/).map(x=>x[0]).slice(0,2).join('').toUpperCase();const items=[['inicio','home','Inicio'],['vencimientos','list','Vencimientos'],['calendario','calendar','Calendario'],['documentos','file','Documentos'],['pagos','pay','Pagos'],['reportes','report','Reportes'],['configuracion','settings','Configuración']];return `<aside class="sidebar"><div class="brand"><img class="nav-brand-logo" src="/impueston-nav-logo.png" alt="Logo de ImpuestON"><div><b>ImpuestON</b><small>agenda personal</small></div></div><nav>${items.map(([v,i,l])=>`<button data-view="${v}" class="${appState.view===v?'active':''}"><span>${icon(i)}</span>${l}</button>`).join('')}</nav><div class="user"><div class="avatar">${initials}</div><div><b>${safe(currentUser?.name)}</b><small>@${safe(currentUser?.username)}</small></div><button id="logout" title="Cerrar sesión">↪</button></div></aside>`}
function enhancedSettings(){const s=appState.settings;const granted='Notification'in window&&Notification.permission==='granted';return `${top('Mi cuenta y agenda','Personalizá tus obligaciones, alertas y perfil.')}<div class="settings-grid"><section class="panel settings-card"><span class="modal-kicker">MI PERFIL</span><div class="profile-summary"><div class="avatar big">${(currentUser?.name||'U').slice(0,2).toUpperCase()}</div><div><h2>${safe(currentUser?.name)}</h2><p>@${safe(currentUser?.username)} · Cuenta local</p></div></div><button class="outline" id="logoutCard">Cerrar sesión</button><p class="hint">La sincronización entre dispositivos estará disponible al conectar el servicio en la nube.</p></section><section class="panel settings-card"><h2>Agregar a mi agenda</h2><p>Creá tus propios impuestos, servicios, seguros o suscripciones.</p><form id="obligationForm" class="inline-form"><label>Nombre<input name="name" required placeholder="Ej. Monotributo"></label><label>Categoría<select name="category"><option>Impuestos</option><option>Servicios</option><option>Comunicaciones</option><option>Alquileres</option><option>Seguros</option><option>Educación</option><option>Software</option><option>Otro</option></select></label><button class="primary" type="submit">＋ Agregar</button></form></section><section class="panel settings-card agenda-card"><div class="panel-head"><div><h2>Mi agenda</h2><p>${obligations.length} obligaciones activas</p></div></div><div class="obligation-list">${obligations.map(o=>`<div><span><b>${safe(o.name)}</b><small>${safe(o.category)}${o.custom?' · Personalizado':''}</small></span>${o.custom?`<button class="delete-obligation" data-delete-obligation="${o.id}" title="Quitar de mi agenda">×</button>`:'<span class="base-label">Sugerido</span>'}</div>`).join('')}</div></section><section class="panel settings-card"><div class="setting-title"><span class="setting-icon">♧</span><div><h2>Alertas</h2><p>Elegí cuándo recibir recordatorios.</p></div><label class="switch"><input id="alertsToggle" type="checkbox" ${s.alerts?'checked':''}><span></span></label></div><div class="setting-row"><div><b>Horario</b><small>Buenos Aires (GMT-3)</small></div><input id="alertTime" type="time" value="${s.time}"></div><div class="checks">${[['7','7 días antes'],['3','3 días antes'],['1','1 día antes'],['0','El mismo día']].map(([v,l])=>`<label><input type="checkbox" data-reminder="${v}" ${s.reminders.includes(v)?'checked':''}> ${l}</label>`).join('')}</div><button class="primary notifications-button" id="enablePush">Activar notificaciones</button><p class="hint" id="pushStatus">${granted?'✓ Notificaciones autorizadas.':'Se solicitará permiso del sistema.'}</p></section></div>`}
function agendaSettings(){
 const html=enhancedSettings();const start='<section class="panel settings-card agenda-card">';const end='<section class="panel settings-card"><div class="setting-title">';const from=html.indexOf(start);const to=html.indexOf(end,from);if(from<0||to<0)return html;
 const activeCount=obligations.filter(o=>o.active!==false).length;
 const agenda=`<section class="panel settings-card agenda-card"><div class="panel-head"><div><h2>Mi agenda</h2><p>${activeCount} activas · ${obligations.length-activeCount} pausadas</p></div></div><div class="obligation-list">${obligations.map(o=>`<div class="${o.active===false?'is-paused':''}"><span><b>${safe(o.name)}</b><small>${safe(o.category)}${o.custom?' · Personalizado':''}</small></span><div class="obligation-actions"><button class="obligation-action" data-edit-obligation="${o.id}" title="Editar obligación">Editar</button><button class="obligation-action ${o.active===false?'activate':'pause'}" data-toggle-obligation="${o.id}" title="${o.active===false?'Activar':'Pausar'} obligación">${o.active===false?'Activar':'Pausar'}</button>${o.custom?`<button class="delete-obligation" data-delete-obligation="${o.id}" title="Quitar de mi agenda" aria-label="Quitar ${safe(o.name)}">×</button>`:''}</div></div>`).join('')}</div></section>`;
 return html.slice(0,from)+agenda+html.slice(to);
}
function enhancedCalendar(){
 const grouped={};appState.records.filter(r=>r.due).sort((a,b)=>a.due.localeCompare(b.due)).forEach(r=>(grouped[r.due]??=[]).push(r));
 return `${top('Calendario','Todos tus compromisos ordenados por fecha.')}<section class="calendar-list">${Object.entries(grouped).length?Object.entries(grouped).map(([date,items])=>`<article class="panel calendar-day"><div class="calendar-date"><b>${new Date(`${date}T12:00:00`).getDate()}</b><span>${new Intl.DateTimeFormat('es-AR',{month:'short'}).format(new Date(`${date}T12:00:00`))}</span></div><div>${items.map(r=>`<button data-view="vencimientos"><b>${r.obligation}</b><small>${r.period} · ${money(r.amount,r.currency)}</small></button>`).join('')}</div></article>`).join(''):`<div class="panel empty-state"><b>Sin fechas cargadas</b><p>Escaneá un comprobante para comenzar.</p><button class="primary" id="uploadPlaceholder">＋ Escanear comprobante</button></div>`}</section>`;
}
function enhancedDocuments(){const docs=[...appState.documents].reverse();return `${top('Documentos','Comprobantes fotografiados, importados y pendientes de revisión.')}<section class="panel settings-card documents-agenda"><h2>Agregar a mi agenda</h2><p>Creá tus propios impuestos, servicios, seguros o suscripciones antes de cargar el documento.</p><form id="obligationForm" class="inline-form"><label>Nombre<input name="name" required placeholder="Ej. Monotributo"></label><label>Categoría<select name="category"><option>Impuestos</option><option>Servicios</option><option>Comunicaciones</option><option>Alquileres</option><option>Seguros</option><option>Educación</option><option>Software</option><option>Otro</option></select></label><button class="primary" type="submit">＋ Agregar</button></form></section><div class="panel documents-panel"><div class="records-head"><b>${docs.length} documentos</b><button class="primary" id="uploadPlaceholder">＋ Nuevo documento</button></div>${docs.length?docs.map(d=>`<article class="document-item"><div class="document-thumb">${d.preview?`<img src="${d.preview}" alt="Vista previa">`:'▤'}</div><div><b>${d.name}</b><small>${d.created} · ${d.type||'Documento'}</small><span class="confidence ${d.confidence||'medium'}">${d.status||'Pendiente de revisar'}</span></div><button class="outline" data-review-document="${d.id}">Revisar</button></article>`).join(''):'<div class="empty-state"><b>Todavía no hay comprobantes</b><p>Tomá una foto o cargá un PDF y quedará respaldado aquí.</p></div>'}</div>`}
function enhancedPayments(){const paid=appState.records.filter(r=>r.status==='paid');const pending=appState.records.filter(r=>r.status!=='paid');return `${top('Pagos','Confirmá pagos y mantené el historial al día.')}<section class="panel records"><div class="records-head"><b>${paid.length} pagos confirmados</b><span>${pending.length} pendientes</span></div><div class="table-wrap"><table><thead><tr><th>Obligación</th><th>Período</th><th>Fecha</th><th>Importe</th><th>Estado</th><th></th></tr></thead><tbody>${paid.length?paid.map(row).join(''):'<tr><td colspan="6" class="empty">Todavía no confirmaste pagos. Usá el menú de un vencimiento.</td></tr>'}</tbody></table></div></section>`}
function enhancedReports(){const current=iso(today).slice(0,7);const month=appState.records.filter(r=>(r.due||'').startsWith(current));const paid=month.filter(r=>r.status==='paid').reduce((s,r)=>s+Number(r.amount||0),0);const pending=month.filter(r=>r.status!=='paid').reduce((s,r)=>s+Number(r.amount||0),0);const taxes=month.filter(r=>r.category==='Impuestos').reduce((s,r)=>s+Number(r.amount||0),0);return `${top('Resumen mensual','Una vista simple para decidir cuánto pagar y reservar.')}<section class="report-grid">${stat('Pagado este mes',money(paid),'Comprobantes confirmados','ok')}${stat('Pendiente',money(pending),'Compromisos del mes','warn')}${stat('Reserva impositiva',money(taxes),'IVA, IIBB y ATM cargados','money')}</section><section class="panel report-card"><div><span class="eyebrow">EXPORTACIÓN</span><h2>Información para tu contador</h2><p>Descargá un CSV compatible con Excel con vencimientos, importes, estado, factura y notas.</p></div><button class="primary" id="exportCsv">Descargar CSV</button></section>`}
function enhancedPlaceholder(){return appState.view==='calendario'?enhancedCalendar():appState.view==='documentos'?enhancedDocuments():appState.view==='pagos'?enhancedPayments():enhancedReports()}
function enhancedRender(){if(!currentUser){authScreen();return}persistUserData();let content=appState.view==='inicio'?dashboard():appState.view==='vencimientos'?recordsView():appState.view==='configuracion'?agendaSettings():enhancedPlaceholder();document.querySelector('#app').innerHTML=`${enhancedNav()}<main>${content}</main>${mobileNav()}<input hidden id="cameraInput" type="file" accept="image/*" capture="environment"><input hidden id="fileInput" type="file" accept="application/pdf,image/jpeg,image/png"><div id="modalRoot"></div><div id="toast"></div>`;bind()}
function enhancedOpenLoadMenu(target=''){document.querySelector('#modalRoot').innerHTML=`<div class="modal-backdrop"><section class="modal choice-modal"><button class="modal-close" data-close>×</button><span class="modal-kicker">NUEVO REGISTRO</span><h2>${target||'Registrar comprobante'}</h2><p>Elegí la opción más cómoda. Siempre podrás revisar los datos antes de guardar.</p><div class="choice-grid three"><button id="chooseCamera"><span>📷</span><b>Sacar foto</b><small>Cámara del teléfono</small></button><button id="chooseFile"><span>⇧</span><b>Subir archivo</b><small>PDF, JPG o PNG</small></button><button id="chooseManual"><span>✎</span><b>Carga manual</b><small>Completar los datos</small></button></div></section></div>`;document.querySelector('[data-close]').onclick=closeModal;document.querySelector('.modal-backdrop').onclick=e=>{if(e.target.classList.contains('modal-backdrop'))closeModal()};const remember=()=>target&&localStorage.setItem('cv_upload_target',target);document.querySelector('#chooseCamera').onclick=()=>{remember();closeModal();document.querySelector('#cameraInput').click()};document.querySelector('#chooseFile').onclick=()=>{remember();closeModal();document.querySelector('#fileInput').click()};document.querySelector('#chooseManual').onclick=()=>openManualForm(target)}
async function storeDocument(file,preview='',extra={}){const id=newUuid();const cleanName=(file.name||'comprobante').replace(/[^a-zA-Z0-9._-]+/g,'-');const storagePath=`${currentUser.id}/${id}/${cleanName}`;const {error}=await supabase.storage.from('documents').upload(storagePath,file,{contentType:file.type||'application/octet-stream',upsert:false});if(error)throw error;const doc={id,name:file.name||'Foto de comprobante',type:file.type||'Imagen',created:new Intl.DateTimeFormat('es-AR',{dateStyle:'short',timeStyle:'short'}).format(new Date()),preview,storagePath,status:'Pendiente de revisar',confidence:'medium',...extra};appState.documents.push(doc);persistUserData();return doc}
async function imagePreview(file){const bitmap=await createImageBitmap(file);const scale=Math.min(1,1600/Math.max(bitmap.width,bitmap.height));const canvas=document.createElement('canvas');canvas.width=Math.round(bitmap.width*scale);canvas.height=Math.round(bitmap.height*scale);canvas.getContext('2d').drawImage(bitmap,0,0,canvas.width,canvas.height);bitmap.close?.();return canvas.toDataURL('image/jpeg',.76)}
async function readQr(file){if(!('BarcodeDetector'in window))return'';try{const bitmap=await createImageBitmap(file);const detector=new BarcodeDetector({formats:['qr_code']});const codes=await detector.detect(bitmap);return codes[0]?.rawValue||''}catch{return''}}
async function enhancedHandleDocument(file){const target=localStorage.getItem('cv_upload_target')||'';localStorage.removeItem('cv_upload_target');if(file.size>15*1024*1024){toast('El archivo supera el máximo de 15 MB.');return}if(file.type==='application/pdf'){toast(`Analizando ${file.name}…`);try{const text=await extractPdf(file);if(!text.trim())throw new Error('Sin texto');await storeDocument(file,'',{status:'Datos extraídos · revisar',confidence:'high'});openPdfReview(pdfDraft(text,target,file.name));toast('Revisá los datos detectados antes de guardar.')}catch(error){console.error(error);try{await storeDocument(file)}catch(uploadError){console.error(uploadError);toast('No se pudo respaldar el PDF en la nube.');return}toast('El PDF es una imagen escaneada. Completá los datos.');openManualForm(target)}return}try{const preview=await imagePreview(file);const qr=await readQr(file);const doc=await storeDocument(file,preview,{status:qr?'QR detectado · revisar':'Foto lista · completar',confidence:qr?'high':'medium',qr});openImageReview(doc,target)}catch(error){console.error(error);toast('No se pudo respaldar la imagen en la nube.')}}
function openImageReview(doc,target=''){document.querySelector('#modalRoot').innerHTML=`<div class="modal-backdrop"><section class="modal form-modal scan-review"><button class="modal-close" data-close>×</button><span class="modal-kicker">COMPROBANTE CAPTURADO</span><h2>Revisar foto</h2><div class="scan-layout"><img src="${doc.preview}" alt="Comprobante fotografiado"><div><span class="confidence ${doc.confidence}">${doc.qr?'Lectura alta · QR detectado':'Revisión necesaria'}</span><p>${doc.qr?'Encontramos un QR del comprobante. Confirmá los datos fiscales para evitar errores.':'La foto quedó guardada como respaldo. Completá los datos principales.'}</p>${doc.qr?`<details><summary>Ver contenido del QR</summary><code>${String(doc.qr).replaceAll('<','&lt;')}</code></details>`:''}<button class="primary full" id="continueImage">Completar datos</button><button class="outline full" data-close>Repetir foto</button></div></div></section></div>`;document.querySelectorAll('[data-close]').forEach(b=>b.onclick=closeModal);document.querySelector('#continueImage').onclick=()=>openManualForm(target)}
function duplicateOf(data){return appState.records.find(r=>r.obligation===data.obligation&&r.period===data.period&&String(r.invoice||'')===String(data.invoice||'')&&Number(r.totalAmount||r.amount)===Number(data.totalAmount||data.amount))}
const originalSaveInstallments=saveInstallments;
saveInstallments=function(data){if(duplicateOf(data)&&!confirm('Parece que este comprobante ya está cargado. ¿Querés guardarlo de todos modos?'))return;originalSaveInstallments(data);const latest=appState.documents.at(-1);if(latest&&latest.status!=='Registrado'){latest.status='Registrado';latest.confidence='high';localStorage.setItem('cv_documents_v1',JSON.stringify(appState.documents))}}
function exportCsv(){const headers=['Obligación','Categoría','Período','Vencimiento','Importe','Moneda','Estado','Factura','Notas'];const quote=v=>`"${String(v??'').replaceAll('"','""')}"`;const lines=[headers,...appState.records.map(r=>[r.obligation,r.category,r.period,r.due,r.amount,r.currency,r.status,r.invoice,r.notes])].map(row=>row.map(quote).join(';')).join('\r\n');const a=document.createElement('a');a.href=URL.createObjectURL(new Blob(['\ufeff'+lines],{type:'text/csv;charset=utf-8'}));a.download=`impueston-${iso(today)}.csv`;a.click();URL.revokeObjectURL(a.href);toast('Archivo preparado para tu contador')}
function recordActions(id){const r=appState.records.find(x=>String(x.id)===String(id));if(!r)return;document.querySelector('#modalRoot').innerHTML=`<div class="modal-backdrop"><section class="modal action-modal"><button class="modal-close" data-close>×</button><h2>${r.obligation}</h2><p>${r.period} · ${money(r.amount,r.currency)}</p><button class="primary full" id="markPaid">✓ Marcar como pagado</button><button class="outline full" data-close>Cancelar</button></section></div>`;document.querySelectorAll('[data-close]').forEach(b=>b.onclick=closeModal);document.querySelector('#markPaid').onclick=()=>{r.status='paid';r.paid=iso(new Date());localStorage.setItem('cv_records_v2',JSON.stringify(appState.records));closeModal();render();toast('Pago confirmado')}}
function editObligation(id){
 const obligation=obligations.find(o=>String(o.id)===String(id));if(!obligation)return;
 document.querySelector('#modalRoot').innerHTML=`<div class="modal-backdrop"><section class="modal form-modal obligation-modal"><button class="modal-close" data-close>×</button><span class="modal-kicker">MI AGENDA</span><h2>Editar obligación</h2><form id="editObligationForm"><label class="wide">Nombre<input name="name" required value="${safe(obligation.name)}"></label><label class="wide">Categoría<select name="category">${['Impuestos','Servicios','Comunicaciones','Alquileres','Seguros','Educación','Software','Otro'].map(category=>`<option ${category===obligation.category?'selected':''}>${category}</option>`).join('')}</select></label><div class="form-actions wide"><button type="button" class="outline" data-close>Cancelar</button><button type="submit" class="primary">Guardar cambios</button></div></form></section></div>`;
 document.querySelectorAll('[data-close]').forEach(b=>b.onclick=closeModal);document.querySelector('.modal-backdrop').onclick=e=>{if(e.target.classList.contains('modal-backdrop'))closeModal()};document.querySelector('#editObligationForm').onsubmit=e=>{e.preventDefault();const data=Object.fromEntries(new FormData(e.currentTarget));const newName=data.name.trim();if(obligations.some(o=>o!==obligation&&normalizeText(o.name)===normalizeText(newName))){toast('Ya existe una obligación con ese nombre');return}const oldName=obligation.name;obligation.name=newName;obligation.category=data.category;appState.records.filter(r=>r.obligation===oldName).forEach(r=>{r.obligation=newName;r.category=data.category});persistUserData();closeModal();render();toast('Obligación actualizada')};
}
const originalBind=bind;
render=enhancedRender;openLoadMenu=enhancedOpenLoadMenu;handleDocument=enhancedHandleDocument;
const legacySaveSettings=saveSettings;saveSettings=function(s){legacySaveSettings(s);persistUserData()};
bind=function(){originalBind();document.querySelector('#logout')?.addEventListener('click',logout);document.querySelector('#logoutCard')?.addEventListener('click',logout);const addForm=document.querySelector('#obligationForm');if(addForm)addForm.onsubmit=e=>{e.preventDefault();const data=Object.fromEntries(new FormData(e.currentTarget));if(obligations.some(o=>normalizeText(o.name)===normalizeText(data.name))){toast('Esa obligación ya está en tu agenda');return}obligations.push({id:`custom-${Date.now()}`,name:data.name.trim(),category:data.category,active:true,notifications:true,custom:true});obligations.sort((a,b)=>a.name.localeCompare(b.name,'es'));persistUserData();render();toast('Agregado a tu agenda')};document.querySelectorAll('[data-delete-obligation]').forEach(b=>b.onclick=()=>{const index=obligations.findIndex(o=>String(o.id)===b.dataset.deleteObligation);if(index>=0){obligations.splice(index,1);persistUserData();render();toast('Obligación quitada de tu agenda')}});const camera=document.querySelector('#cameraInput');if(camera)camera.onchange=async()=>{const file=camera.files[0];if(file)await handleDocument(file);camera.value=''};document.querySelectorAll('[data-review-document]').forEach(b=>b.onclick=()=>{const d=appState.documents.find(x=>String(x.id)===b.dataset.reviewDocument);if(d?.preview)openImageReview(d);else openManualForm()});document.querySelectorAll('.more').forEach(b=>b.onclick=()=>recordActions(b.closest('tr')?.dataset.id));const exp=document.querySelector('#exportCsv');if(exp)exp.onclick=exportCsv}

const obligationsBind=bind;
bind=function(){obligationsBind();document.querySelectorAll('[data-edit-obligation]').forEach(b=>b.onclick=()=>editObligation(b.dataset.editObligation));document.querySelectorAll('[data-toggle-obligation]').forEach(b=>b.onclick=()=>{const obligation=obligations.find(o=>String(o.id)===b.dataset.toggleObligation);if(!obligation)return;obligation.active=obligation.active===false;persistUserData();render();toast(obligation.active?'Obligación activada':'Obligación pausada')})}

const statusBind=bind;
bind=function(){statusBind();document.querySelectorAll('[data-set-status]').forEach(button=>button.onclick=()=>{const record=appState.records.find(item=>String(item.id)===String(button.closest('tr')?.dataset.id));if(!record||record.status===button.dataset.setStatus)return;record.status=button.dataset.setStatus;if(record.status==='paid')record.paid=iso(new Date());else delete record.paid;persistUserData();render();toast(record.status==='paid'?'Pago confirmado':'Marcado como pendiente')})}

const ADMIN_USERNAME='admin';
const ADMIN_PASSWORD='admin';
function adminLoginScreen(message=''){
 document.querySelector('#app').innerHTML=`<main class="admin-auth-shell"><section class="auth-card admin-auth-card"><button class="auth-back" id="backToUsers">← Volver</button><span class="modal-kicker">ADMINISTRACIÓN</span><h2>Panel de usuarios</h2><p>Ingresá con las credenciales administrativas del dispositivo.</p>${message?`<div class="auth-message">${safe(message)}</div>`:''}<form id="adminLoginForm"><label>Usuario<input name="username" autocomplete="username" required></label><label>Contraseña<input name="password" type="password" autocomplete="current-password" required></label><button class="primary full" type="submit">Ingresar al panel</button></form><small>Este acceso permite restablecer contraseñas locales.</small></section></main>`;
 document.querySelector('#backToUsers').onclick=()=>authScreen(accounts().length?'login':'register');
 document.querySelector('#adminLoginForm').onsubmit=e=>{e.preventDefault();const data=Object.fromEntries(new FormData(e.currentTarget));if(data.username!==ADMIN_USERNAME||data.password!==ADMIN_PASSWORD){adminLoginScreen('Usuario o contraseña de administrador incorrectos.');return}sessionStorage.setItem('impueston_admin','1');adminPanel()};
}
function adminUserStats(user){const read=suffix=>{try{return JSON.parse(localStorage.getItem(`impueston_${user.id}_${suffix}`)||'[]')}catch{return[]}};return {records:read('records').length,documents:read('documents').length,obligations:read('obligations').length}}
function adminPanel(){
 if(sessionStorage.getItem('impueston_admin')!=='1'){adminLoginScreen();return}const users=accounts();
 document.querySelector('#app').innerHTML=`<main class="admin-shell"><header class="admin-top"><div><span class="modal-kicker">ADMINISTRACIÓN LOCAL</span><h1>Usuarios registrados</h1><p>${users.length} ${users.length===1?'cuenta registrada':'cuentas registradas'} en este dispositivo</p></div><button class="outline" id="adminLogout">Cerrar panel</button></header><section class="panel admin-users">${users.length?users.map(user=>{const stats=adminUserStats(user);return `<article class="admin-user" data-admin-user="${user.id}"><div class="avatar">${safe(user.name).slice(0,2).toUpperCase()}</div><div class="admin-user-main"><b>${safe(user.name)}</b><span>@${safe(user.username)}</span><small>Creada ${new Intl.DateTimeFormat('es-AR',{dateStyle:'medium'}).format(new Date(user.created))}</small></div><div class="admin-user-stats"><span><b>${stats.obligations}</b> obligaciones</span><span><b>${stats.records}</b> vencimientos</span><span><b>${stats.documents}</b> documentos</span></div><button class="outline" data-reset-password="${user.id}">Restablecer contraseña</button></article>`}).join(''):'<div class="empty-state"><b>No hay usuarios registrados</b><p>Las cuentas aparecerán aquí cuando alguien se registre.</p></div>'}</section><div id="modalRoot"></div><div id="toast"></div></main>`;
 document.querySelector('#adminLogout').onclick=()=>{sessionStorage.removeItem('impueston_admin');authScreen(accounts().length?'login':'register')};document.querySelectorAll('[data-reset-password]').forEach(button=>button.onclick=()=>adminPasswordModal(button.dataset.resetPassword));
}
function adminPasswordModal(userId){
 const user=accounts().find(item=>item.id===userId);if(!user)return;
 document.querySelector('#modalRoot').innerHTML=`<div class="modal-backdrop"><section class="modal form-modal admin-reset-modal"><button class="modal-close" data-close>×</button><span class="modal-kicker">SOPORTE DE CUENTA</span><h2>Restablecer contraseña</h2><p>Creá una contraseña temporal para <b>${safe(user.name)}</b> (@${safe(user.username)}). Al ingresar, deberá reemplazarla por una nueva.</p><form id="adminPasswordForm"><label>Contraseña temporal<input name="password" type="password" minlength="6" autocomplete="new-password" required placeholder="Mínimo 6 caracteres"></label><label>Repetir contraseña temporal<input name="confirmation" type="password" minlength="6" autocomplete="new-password" required></label><div class="form-actions"><button type="button" class="outline" data-close>Cancelar</button><button type="submit" class="primary">Guardar contraseña temporal</button></div></form></section></div>`;
 const close=()=>document.querySelector('#modalRoot').innerHTML='';document.querySelectorAll('[data-close]').forEach(button=>button.onclick=close);document.querySelector('#adminPasswordForm').onsubmit=async e=>{e.preventDefault();const data=Object.fromEntries(new FormData(e.currentTarget));if(data.password!==data.confirmation){toast('Las contraseñas no coinciden');return}const list=accounts();const account=list.find(item=>item.id===userId);if(!account)return;account.salt=crypto.randomUUID();account.passwordHash=await passwordHash(data.password,account.salt);account.mustChangePassword=true;saveAccounts(list);close();toast(`Contraseña temporal de ${account.username} actualizada`)};
}
function requiredPasswordChangeScreen(user,message=''){
 document.querySelector('#app').innerHTML=`<main class="admin-auth-shell password-change-shell"><section class="auth-card admin-auth-card"><span class="modal-kicker">ACCIÓN REQUERIDA</span><h2>Creá una contraseña nueva</h2><p>Ingresaste con una contraseña temporal. Para proteger tu cuenta, tenés que reemplazarla antes de continuar.</p>${message?`<div class="auth-message">${safe(message)}</div>`:''}<form id="requiredPasswordForm"><label>Nueva contraseña<input name="password" type="password" minlength="6" autocomplete="new-password" required placeholder="Mínimo 6 caracteres"></label><label>Repetir contraseña<input name="confirmation" type="password" minlength="6" autocomplete="new-password" required></label><button class="primary full" type="submit">Cambiar contraseña e ingresar</button></form><button class="auth-switch" id="cancelPasswordChange">Volver al ingreso</button></section></main>`;
 document.querySelector('#cancelPasswordChange').onclick=()=>authScreen('login');document.querySelector('#requiredPasswordForm').onsubmit=async e=>{e.preventDefault();const data=Object.fromEntries(new FormData(e.currentTarget));if(data.password!==data.confirmation){requiredPasswordChangeScreen(user,'Las contraseñas no coinciden.');return}const list=accounts();const account=list.find(item=>item.id===user.id);if(!account){authScreen('login','La cuenta ya no está disponible.');return}const nextHash=await passwordHash(data.password,account.salt);if(nextHash===account.passwordHash){requiredPasswordChangeScreen(user,'La contraseña nueva debe ser diferente de la temporal.');return}account.salt=crypto.randomUUID();account.passwordHash=await passwordHash(data.password,account.salt);delete account.mustChangePassword;saveAccounts(list);sessionStorage.setItem('impueston_session',account.id);loadUserData(account);render();toast('Contraseña actualizada correctamente')};
}
const regularSubmitAuth=submitAuth;
submitAuth=async function(event,mode){
 if(mode==='register')return regularSubmitAuth(event,mode);event.preventDefault();const data=Object.fromEntries(new FormData(event.currentTarget));const username=(data.name||'').trim().toLowerCase();const user=accounts().find(item=>item.username===username);if(!user||await passwordHash(data.password,user.salt)!==user.passwordHash){authScreen('login','Usuario o contraseña incorrectos.');return}if(user.mustChangePassword){sessionStorage.removeItem('impueston_session');requiredPasswordChangeScreen(user);return}sessionStorage.setItem('impueston_session',user.id);loadUserData(user);render();
}
const regularAuthScreen=authScreen;
authScreen=function(mode='login',message=''){regularAuthScreen(mode,message);const card=document.querySelector('.auth-card');if(!card)return;const button=document.createElement('button');button.type='button';button.className='admin-access';button.textContent='Acceso administrador';button.onclick=()=>adminLoginScreen();card.appendChild(button)};

// Supabase becomes the source of truth. localStorage remains only as a fast device cache.
let cloudReady=false;
let cloudSyncTimer;
let cloudSyncChain=Promise.resolve();
const uuidPattern=/^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i;
const newUuid=()=>{
 if(globalThis.crypto?.randomUUID)return globalThis.crypto.randomUUID();
 const bytes=new Uint8Array(16);if(globalThis.crypto?.getRandomValues)globalThis.crypto.getRandomValues(bytes);else for(let index=0;index<bytes.length;index++)bytes[index]=Math.floor(Math.random()*256);
 bytes[6]=(bytes[6]&15)|64;bytes[8]=(bytes[8]&63)|128;const hex=[...bytes].map(value=>value.toString(16).padStart(2,'0')).join('');return `${hex.slice(0,8)}-${hex.slice(8,12)}-${hex.slice(12,16)}-${hex.slice(16,20)}-${hex.slice(20)}`
};
const ensureUuid=item=>{if(!uuidPattern.test(String(item.id||'')))item.id=newUuid();return item};
const cloudUser=user=>({id:user.id,name:user.user_metadata?.display_name||user.email?.split('@')[0]||'Usuario',username:user.email||''});
const cacheCloudData=()=>{if(!currentUser)return;localStorage.setItem(userKey('records'),JSON.stringify(appState.records));localStorage.setItem(userKey('documents'),JSON.stringify(appState.documents));localStorage.setItem(userKey('settings'),JSON.stringify(appState.settings));localStorage.setItem(userKey('obligations'),JSON.stringify(obligations))};
async function replaceCloudRows(table,rows){
 const {data:remote,error:readError}=await supabase.from(table).select('id');if(readError)throw readError;
 const localIds=new Set(rows.map(row=>row.id));const removed=(remote||[]).filter(row=>!localIds.has(row.id)).map(row=>row.id);
 if(removed.length){const {error}=await supabase.from(table).delete().in('id',removed);if(error)throw error}
 if(rows.length){const {error}=await supabase.from(table).upsert(rows,{onConflict:'id'});if(error)throw error}
}
async function syncCloudData(){
 if(!cloudReady||!supabase||!currentUser)return;
 obligations.forEach(ensureUuid);appState.records.forEach(ensureUuid);appState.documents.forEach(ensureUuid);cacheCloudData();
 const obligationByName=new Map(obligations.map(item=>[item.name,item.id]));
 await replaceCloudRows('obligations',obligations.map(item=>({id:item.id,user_id:currentUser.id,name:item.name,category:item.category,active:item.active!==false,notifications:item.notifications!==false,is_custom:Boolean(item.custom)})));
 await replaceCloudRows('records',appState.records.map(item=>({id:item.id,user_id:currentUser.id,obligation_id:obligationByName.get(item.obligation)||null,obligation_name:item.obligation,category:item.category||'',period:item.period,due_on:item.due,issued_on:item.issued||null,paid_on:item.paid||null,amount:item.amount??null,total_amount:item.totalAmount??item.amount??null,currency:item.currency||'ARS',status:item.status||'pending',installment:item.installment||'',invoice:item.invoice||'',notes:item.notes||''})));
 await replaceCloudRows('documents',appState.documents.map(item=>({id:item.id,user_id:currentUser.id,name:item.name,mime_type:item.type||'',storage_path:item.storagePath||null,status:item.status||'Pendiente de revisar',confidence:item.confidence||'medium',qr_content:item.qr||null})));
 const {error}=await supabase.from('user_settings').upsert({user_id:currentUser.id,notification_time:appState.settings.time||'09:00',reminder_days:(appState.settings.reminders||[]).map(Number),alerts_enabled:appState.settings.alerts!==false},{onConflict:'user_id'});if(error)throw error;
}
function scheduleCloudSync(){clearTimeout(cloudSyncTimer);cloudSyncTimer=setTimeout(()=>{cloudSyncChain=cloudSyncChain.then(syncCloudData).catch(error=>{console.error(error);toast('No se pudieron sincronizar los cambios')})},250)}
persistUserData=function(){cacheCloudData();scheduleCloudSync()};
async function loadCloudData(user){
 currentUser=cloudUser(user);cloudReady=false;
 const [obligationsResult,recordsResult,documentsResult,settingsResult]=await Promise.all([
  supabase.from('obligations').select('*').order('name'),supabase.from('records').select('*').order('due_on'),supabase.from('documents').select('*').order('created_at'),supabase.from('user_settings').select('*').maybeSingle()
 ]);
 const failure=[obligationsResult,recordsResult,documentsResult,settingsResult].find(result=>result.error);if(failure)throw failure.error;
 let remoteObligations=obligationsResult.data||[];
 if(!remoteObligations.length){
  const seeds=baseObligations.map(item=>({id:newUuid(),user_id:user.id,name:item.name,category:item.category,active:true,notifications:true,is_custom:false}));
  const {data,error}=await supabase.from('obligations').insert(seeds).select();if(error)throw error;remoteObligations=data;
 }
 obligations.splice(0,obligations.length,...remoteObligations.map(item=>({id:item.id,name:item.name,category:item.category,active:item.active,notifications:item.notifications,custom:item.is_custom})));
 appState.records=(recordsResult.data||[]).map(item=>({id:item.id,obligation:item.obligation_name,category:item.category,period:item.period,due:item.due_on,issued:item.issued_on||'',paid:item.paid_on||'',amount:item.amount==null?null:Number(item.amount),totalAmount:item.total_amount==null?null:Number(item.total_amount),currency:item.currency,status:item.status,installment:item.installment,invoice:item.invoice,notes:item.notes}));
 const cachedDocuments=JSON.parse(localStorage.getItem(userKey('documents'))||'[]');const previews=new Map(cachedDocuments.map(item=>[String(item.id),item.preview]));const storedPaths=(documentsResult.data||[]).map(item=>item.storage_path).filter(Boolean);const signedUrls=new Map();
 if(storedPaths.length){const {data:signed,error:signedError}=await supabase.storage.from('documents').createSignedUrls(storedPaths,3600);if(signedError)console.error(signedError);else (signed||[]).forEach(item=>signedUrls.set(item.path,item.signedUrl))}
 appState.documents=(documentsResult.data||[]).map(item=>({id:item.id,name:item.name,type:item.mime_type,created:new Intl.DateTimeFormat('es-AR',{dateStyle:'short',timeStyle:'short'}).format(new Date(item.created_at)),preview:item.mime_type?.startsWith('image/')?(signedUrls.get(item.storage_path)||previews.get(String(item.id))||''):'',storagePath:item.storage_path||'',status:item.status,confidence:item.confidence,qr:item.qr_content||''}));
 const settings=settingsResult.data;appState.settings=settings?{time:String(settings.notification_time).slice(0,5),reminders:(settings.reminder_days||[]).map(String),alerts:settings.alerts_enabled}:{time:'09:00',reminders:['7','3','1','0'],alerts:true};
 cloudReady=true;cacheCloudData();
}
authScreen=function(mode='login',message=''){
 if(!isSupabaseConfigured){document.querySelector('#app').innerHTML='<main class="admin-auth-shell"><section class="auth-card admin-auth-card"><h2>Falta configurar Supabase</h2><p>Revisá las variables VITE_SUPABASE_URL y VITE_SUPABASE_PUBLISHABLE_KEY.</p></section></main>';return}
 document.querySelector('#app').innerHTML=`<main class="auth-shell"><section class="auth-brand"><img class="auth-logo" src="/impueston-nav-logo.png" alt="ImpuestON"><span>IMPUES<span>TON</span></span><h1>Tu agenda impositiva,<br>simple y personal.</h1><p>Organizá impuestos, servicios, comprobantes y vencimientos desde cualquier dispositivo.</p><div class="auth-features"><span>✓ Sincronización segura</span><span>✓ Datos privados por usuario</span><span>✓ Acceso desde cualquier equipo</span></div></section><section class="auth-card"><span class="modal-kicker">${mode==='register'?'CREAR CUENTA':'BIENVENIDO'}</span><h2>${mode==='register'?'Empezá a organizarte':'Ingresá a ImpuestON'}</h2><p>${mode==='register'?'Creá tu cuenta segura en la nube.':'Accedé a tu agenda y tus documentos.'}</p>${message?`<div class="auth-message">${safe(message)}</div>`:''}<form id="authForm">${mode==='register'?'<label>Tu nombre<input name="displayName" autocomplete="name" required placeholder="Ej. Fernando"></label>':''}<label>Correo electrónico<input name="email" type="email" autocomplete="email" required placeholder="nombre@correo.com"></label><label>Contraseña<input name="password" type="password" autocomplete="${mode==='register'?'new-password':'current-password'}" minlength="6" required placeholder="Mínimo 6 caracteres"></label><button class="primary full" type="submit">${mode==='register'?'Crear mi cuenta':'Ingresar'}</button></form><button class="auth-switch" id="switchAuth">${mode==='register'?'Ya tengo una cuenta':'Crear una cuenta'}</button><small>Tu información está protegida mediante Supabase Auth.</small></section></main>`;
 document.querySelector('#switchAuth').onclick=()=>authScreen(mode==='login'?'register':'login');document.querySelector('#authForm').onsubmit=event=>submitAuth(event,mode)
};
submitAuth=async function(event,mode){
 event.preventDefault();const button=event.currentTarget.querySelector('button[type="submit"]');button.disabled=true;const data=Object.fromEntries(new FormData(event.currentTarget));
 try{if(mode==='register'){const {data:result,error}=await supabase.auth.signUp({email:data.email.trim(),password:data.password,options:{data:{display_name:data.displayName.trim()}}});if(error)throw error;if(!result.session){authScreen('login','Revisá tu correo para confirmar la cuenta antes de ingresar.');return}await loadCloudData(result.user);render();toast('Cuenta creada correctamente')}else{const {data:result,error}=await supabase.auth.signInWithPassword({email:data.email.trim(),password:data.password});if(error)throw error;await loadCloudData(result.user);render()}}catch(error){authScreen(mode,error.message||'No se pudo completar el acceso.')}
};
logout=async function(){cloudReady=false;await supabase.auth.signOut();currentUser=null;authScreen('login')};
async function startApp(){
 if(!isSupabaseConfigured){authScreen();return}const {data:{session},error}=await supabase.auth.getSession();if(error){authScreen('login',error.message);return}if(!session){authScreen('login');return}
 try{await loadCloudData(session.user);render()}catch(loadError){console.error(loadError);authScreen('login','No se pudieron cargar tus datos de Supabase.')}
}

if('serviceWorker'in navigator)navigator.serviceWorker.register('/sw.js');
await startApp();
